public class CustomLocalizer : ITmLocalizer
{
    private readonly IStringLocalizer<Resources> _localizer;

    public CustomLocalizer(IStringLocalizer<Resources> localizer)
    {
        _localizer = localizer;
    }

    public string GetString(string key) => _localizer[key];

    public string GetString(string key, params object?[] args) => 
        string.Format(_localizer[key], args);

    public CultureInfo CurrentCulture => CultureInfo.CurrentUICulture;
}

// Program.cs
builder.Services.AddSingleton<ITmLocalizer, CustomLocalizer>();

// Or use built-in
builder.Services.AddTempoBlazor(); // Registers default localizer
